arguments.command:
cat > tests/prune_test.sh <<'EOF'
#!/bin/bash
# prune: sweeps var/audit with the 400-day retention (ADR-0015); never touches var/log.
fail=0
d=$(mktemp -d)
mkdir -p "$d/var/audit" "$d/var/log/shift"
touch -d '401 days ago' "$d/var/audit/old.log"
touch -d '399 days ago' "$d/var/audit/keep399.log"
touch -d '100 days ago' "$d/var/audit/keep100.log"
touch -d '401 days ago' "$d/var/log/shift/other.log"
out=$(RELAY_ROOT=$d bash bin/prune --dry-run) || { echo "prune dry-run"; fail=1; }
[ "$out" = "$d/var/audit/old.log" ] || { echo "dry-run list: $out"; fail=1; }
RELAY_ROOT=$d bash bin/prune >/dev/null
[ -e "$d/var/audit/old.log" ] && { echo "old not removed"; fail=1; }
[ -e "$d/var/audit/keep399.log" ] && [ -e "$d/var/audit/keep100.log" ] || { echo "kept file removed"; fail=1; }
[ -e "$d/var/log/shift/other.log" ] || { echo "var/log touched"; fail=1; }
rm -rf "$d"
d=$(mktemp -d)
RELAY_ROOT=$d bash bin/prune --dry-run >/dev/null || { echo "prune empty root"; fail=1; }
rm -rf "$d"
exit $fail
EOF
bash tests/prune_test.sh; echo $?

