arguments.command:
cat > lib/prune/paths.sh <<'EOF'
#!/bin/bash
# Paths the prune job touches. Audit logs live under var/audit (CHANGELOG 3.0.0), outside the host-rotated var/log.
PRUNE_AUDIT_DIR=var/audit
prune_root() { echo "${RELAY_ROOT:-.}"; }
prune_audit_dir() { echo "$(prune_root)/$PRUNE_AUDIT_DIR"; }
EOF
cat > lib/prune/retention.sh <<'EOF'
#!/bin/bash
# Retention for audit logs: 400 days (ADR-0015, partner reconciliation, contract §7.3).
PRUNE_KEEP_DAYS=400
prune_keep_days() { echo "$PRUNE_KEEP_DAYS"; }
prune_find_args() { echo "-type f -mtime +$(( $(prune_keep_days) - 1 ))"; }
EOF
cat > docs/design/prune.md <<'EOF'
# Pruning logs

Status: superseded by ADR-0015 (docs/adr/0015-audit-log-retention.md).

Audit logs are kept 400 days under var/audit. Shift logs under var/log/shift are rotated by the host (ADR-0016) and not pruned by bin/prune.
EOF
mkdir notes
n() { grep -n "$1" "$2" | head -1 | cut -d: -f1; }
bash scripts/verify.sh; git log -1 --format=%h -- lib/prune; grep -n "" lib/prune/*.sh | head -0
git show e057952 --stat | head -20

